const title=m=>m?.localized&&m?.name||russianTitles[m?.id]||m?.name||'Фильм';
function trailers(m){const ids=new Set();for(const item of [...(Array.isArray(m?.trailerStreams)?m.trailerStreams:[]),...(Array.isArray(m?.trailers)?m.trailers:[])]){if(!item||item.type&&item.type!=='Trailer')continue;const id=item.ytId||item.source;if(typeof id==='string'&&/^[A-Za-z0-9_-]{11}$/.test(id))ids.add(id);}return [...ids];}
const year=m=>String(m?.year||m?.releaseInfo||'').slice(0,4);
const genres={Biography:'Биография',Action:'Боевик',Adventure:'Приключения',Animation:'Анимация',Comedy:'Комедия',Crime:'Криминал',Documentary:'Документальный',Drama:'Драма',Family:'Семейный',Fantasy:'Фэнтези',History:'История',Horror:'Ужасы',Music:'Музыка',Mystery:'Детектив',Romance:'Мелодрама','Sci-Fi':'Фантастика',Thriller:'Триллер',War:'Военный',Western:'Вестерн',Sport:'Спорт',Short:'Короткометражный',Musical:'Мюзикл','Science Fiction':'Фантастика','TV Movie':'Телефильм',Reality:'Реалити-шоу','Reality-TV':'Реалити-шоу','Talk-Show':'Ток-шоу','Game-Show':'Телеигра','Мультфильм':'Анимация','Мультфильмы':'Анимация'};
