const loading=label=>`<div class="loading"><span class="spinner"></span><span class="loading-label">${esc(label)}</span></div>`;
const hints=items=>`<footer class="hints">${items.map(([k,t])=>`<span><kbd>${k}</kbd>${t}</span>`).join('')}<span class="footer-time">Смотрим · 0.6.7</span></footer>`;
