function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="brand-mark"></span>Смотрим</div><nav class="side-nav">${[['home','home','Главная'],['search','search','Поиск'],['tv','tv','Телеканалы'],['catalog','film','Фильмы'],['series','film','Сериалы'],['saved','heart','Избранное']].map(([id,ic,name])=>btn('nav:'+id,icon(ic)+name,'side-item '+((screen===id||id==='search'&&screen==='results')?'active':''),'nav-'+id,screen===id?'aria-current="page"':'')).join('')}</nav><div class="side-bottom">${btn('nav:settings',icon('settings')+'Настройки','side-item '+(screen==='settings'?'active':''),'nav-settings',screen==='settings'?'aria-current="page"':'')}</div></aside>`;}
function meta(m){return `<div class="meta">${m.imdbRating?`<span class="rating">★ ${esc(m.imdbRating)}</span>`:''}<span>${esc(year(m))}</span><span>${esc(genreText(m))}</span>${m.runtime?`<span class="tag">${esc(m.runtime.replace('min','мин'))}</span>`:''}</div>`;}
function card(m,i){return btn('movie:'+m.id,`<div class="poster" ${art(m.background||m.poster)}>${m.imdbRating?`<span class="quality">★ ${esc(m.imdbRating)}</span>`:''}</div><span class="movie-title">${esc(title(m))}</span><div class="movie-meta">${esc([year(m),mediaKind(m),genreText(m)].filter(Boolean).join(' · '))}</div>`,'movie-card','movie-'+m.id,`data-grid="${i}" ${i===0?'data-initial':''}`);}
