 const seriesHelp=`<h2>Карточки сериалов</h2><p class="lead">Найдите сериал, затем выберите сезон и серию.</p><p class="small-label">В результатах будет кнопка «Искать по раздачам», если нужной карточки нет.</p>`;
 return `${sidebar()}${clock()}<section class="main search-page"><div class="section-heading"><h1 class="page-title">${isChannels?'Поиск каналов':searchMode==='torrents'?'Поиск по раздачам':isSeries?'Найти сериал':'Поиск фильмов и шоу'}</h1><div class="chips search-modes">${btn('search-mode:all','Всё','chip '+(searchMode==='all'?'selected':''))}${btn('search-mode:movies','Фильмы','chip '+(searchMode==='movies'?'selected':''))}${btn('search-mode:series','Сериалы','chip '+(isSeries?'selected':''))}${btn('search-mode:show','Шоу','chip '+(searchMode==='show'?'selected':''))}${btn('search-mode:channels','ТВ','chip '+(isChannels?'selected':''))}</div></div><div class="search-input-row">${btn('input-search',queryDisplay(text),'search-query','search-query',`data-initial aria-label="Поисковый запрос: ${esc(text||'пусто')}"`)}${btn('voice-search:movies',icon('mic'),'button cursor-button','search-voice','aria-label="Голосовой поиск фильмов и шоу"')}${btn('cursor:-1',icon('back'),'button cursor-button',undefined,'aria-label="Курсор влево"')}${btn('cursor:1',icon('arrow'),'button cursor-button',undefined,'aria-label="Курсор вправо"')}</div><div class="search-layout"><div><div class="keyboard">${letters.map(k=>btn('key:'+k,k,'key')).join('')}${btn('space','Пробел','key wide')}${btn('erase',icon('backspace'),'key wide',undefined,'aria-label="Удалить букву слева от курсора"')}</div><div class="search-actions">${btn('search-submit',isChannels?'Показать':isSeries?'Найти':'Найти','button primary','search-submit')}${btn('keyboard',keyboard==='ru'?'ABC · 123':'АБВ','button')}${btn('clear','Очистить','button')}</div><p class="small-label">← → — курсор · ↓ — буквы · OK — клавиатура ТВ</p></div><div class="search-side">${searchMode==='torrents'?'<h2>Поиск вариантов просмотра</h2><p class="lead">Введите название, при необходимости — год, сезон или серию. Здесь поиск идёт сразу по раздачам.</p>':isSeries?seriesHelp:results}</div></div></section>${hints([['OK','выбрать'],['↑ ↓ ← →','перемещение'],['Назад','вернуться']])}`;
