 const e=document.createElement('div');e.className='overlay';e.dataset.returnFocus='clear-history';
 e.innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-labelledby="clear-history-title"><h2 id="clear-history-title">Очистить историю просмотра?</h2><p>Фильмы исчезнут из «Продолжить просмотр». Сохранённые позиции будут удалены. Избранное останется.</p>${btn('close-overlay','Отмена','button primary')}${btn('confirm-clear-history','Очистить историю','button')}</section>`;
