 if(type==='input'){if(data.kind==='search-channel'){applyChannelSearch(data.value);}else if(data.kind==='search'){if(!['all','movies','series','show','torrents'].includes(searchMode))searchMode='all';editQuery(data.value);submitSearch();}else if(data.kind==='magnet'&&data.value){const m=screen==='sources'?movie:{name:'Видео по magnet-ссылке',id:''};start({kind:'torrent',url:data.value,title:m.name,movie:m});}return;}
