  const wasLoading=playState.loading;playState=data;sleepState={remaining:data.sleepRemaining||0,episode:!!data.sleepEpisode};const diagnostics=document.getElementById('diagnostic-content');if(diagnostics)diagnostics.innerHTML=diagnosticContent();if(data.position>0&&Date.now()-lastSaved>5000){savePosition(data.position);lastSaved=Date.now();}if(wasLoading&&!data.loading){loadingMessage='Буферизация…';scheduleHide();}
  const put=(id,text)=>{const el=document.getElementById(id);if(el)el.textContent=text;};
  put('elapsed',playing.kind==='live'?'В эфире':time(data.position));put('duration',playing.kind==='live'?'':time(data.duration));put('transfer',playing.kind==='torrent'?transferText(data):'Подключаемся к источнику');put('player-description',playing.kind==='live'?'● Прямой эфир':transferText(data));
