function historyRows(includeCompleted=false){return Object.entries(history).map(([key,r])=>({...r,key})).filter(r=>includeCompleted||!r.completed).sort((a,b)=>b.updated-a.updated);}
function historyScreen(){return `${sidebar()}${clock()}<section class="main history-page"><h1 class="page-title">История просмотра</h1><p class="lead">Выберите видео: продолжить, начать сначала или убрать из списка.</p><div class="history-list scroll">${historyRows(true).map(r=>btn('history-item:'+r.key,`<span><strong>${esc(title(r.movie))}</strong><small>${esc(r.episode||'')}${r.completed?' · Просмотрено':' · '+time(r.position)}</small></span><span>Действия →</span>`,'button history-row',undefined,'')).join('')||'<p class="empty">Здесь появятся фильмы и серии, которые вы начали смотреть.</p>'}</div></section>${hints([['OK','действия'],['Назад','вернуться']])}`;}
function historyMenu(key){const r=history[key];if(!r)return;modal(title(r.movie),`<p>${esc(r.episode||'')}${r.completed?' · Просмотрено':' · Остановились на '+time(r.position)}</p><div class="tool-list">${btn('history-play:'+key,'Продолжить с '+time(r.position),'button primary')}${btn('history-restart:'+key,'Смотреть сначала','button')}${btn('history-watched:'+key,r.completed?'Вернуть в «Продолжить просмотр»':'Отметить просмотренным','button')}${btn('history-remove:'+key,'Убрать из истории','button')}${btn('close-overlay','Назад','button')}</div>`);}
