function preferenceDialog(){const lang={ru:'Русский',en:'Английский',uk:'Украинский',auto:'Как в видео'};if(!lang[preferences.language])lang[preferences.language]=preferences.language;modal('Качество и язык',`<p>Сначала варианты с нужным языком в названии раздачи, затем — с выбранным качеством. Состав дорожек проверяется в плеере.</p><h3>Предпочитать качество</h3><div class="chips">${[['auto','Любое'],['720','720p'],['1080','1080p'],['2160','4K']].map(([v,label])=>btn('pref-quality:'+v,label,'chip '+(preferences.quality===v?'selected':''),undefined,`aria-pressed="${preferences.quality===v}"`)).join('')}</div><h3>Язык звука</h3><div class="chips">${Object.entries(lang).map(([v,label])=>btn('pref-language:'+v,label,'chip '+(preferences.language===v?'selected':''),undefined,`aria-pressed="${preferences.language===v}"`)).join('')}</div><div class="tool-list">${btn('pref-subtitles','Субтитры: '+(preferences.subtitles?'включены':'выключены'),'button')}${btn('close-overlay','Готово','button primary')}</div><p class="small-label">Это язык звука, а не описаний. В плеере можно выбрать дорожку отдельно. Русские описания подключаются в разделе «Каталоги фильмов и сериалов».</p>`,'preferences');}
async function savePreferences(change){if(preferenceSaving)return;preferenceSaving=true;const key=document.activeElement?.dataset.key;try{const next={...preferences,...change};preferences=await rpc('preferences-set',next);storage.set('preferences',preferences);if(screen==='sources'){sources=movie.selectedEpisode?F.episodeSources(sources,movie.selectedEpisode,preferences):F.rankedSources(sources,preferences);render();}preferenceDialog();focus(findKey(key));}catch(e){toast(e.message);}finally{preferenceSaving=false;}}
async function loadGuide(force=false){if(epgBusy)return;epgBusy=true;epgRequested=Date.now();try{epg=await rpc('epg',{refresh:force});}catch(e){epg={channels:{},error:e.message};}finally{epgBusy=false;if(screen==='tv'){const el=document.getElementById('tv-preview');if(el){const key=el.contains(document.activeElement)?document.activeElement.dataset.key:null;el.innerHTML=preview();if(key)focus(findKey(key));}}if(tv.querySelector('.guide-sheet'))guideDialog();}}
const epgTime=t=>new Date(t).toLocaleTimeString('ru',{hour:'2-digit',minute:'2-digit'});
function channelGuide(c){if(!c)return '';const raw=epg.channels?.[c.url],items=[raw?.current,...(raw?.programs||[])].filter(Boolean),g=raw?{current:items.find(p=>p.start<=Date.now()&&p.end>Date.now()),next:items.find(p=>p.start>Date.now())}:null,p=g?.current,active=p&&p.start<=Date.now()&&p.end>Date.now();return `<div class="now-next">${active?`<strong>${esc(p.title)}</strong><small>Сейчас · до ${epgTime(p.end)} · осталось ${Math.ceil((p.end-Date.now())/60000)} мин</small>`:`<small>${epgBusy?'Загружаем программу…':'Нет программы текущего эфира'}</small>`}${g?.next?`<small>Далее · ${epgTime(g.next.start)} · ${esc(g.next.title)}</small>`:''}${epg.error?'<small>Обновление недоступно · сохранённые данные</small>':''}</div>`;}
function guideDialog(){const c=playing?.kind==='live'?playing.channel:channels[channel],g=epg.channels?.[c?.url],list=[g?.current,...(g?.programs||[])].filter(p=>p&&p.end>Date.now());modal('Программа · '+(c?.name||'Телеканал'),`<div class="guide-programs scroll">${list.map(p=>`<div class="programme"><span>${epgTime(p.start)}–${epgTime(p.end)}</span><strong>${esc(p.title)}</strong></div>`).join('')||`<p>${epgBusy?'Загружаем программу…':'Для этого канала нет актуальной программы. Можно указать свой источник XMLTV в настройках.'}</p>`}</div><p class="small-label">${epg.error?esc(epg.error)+' · ':''}Программа может меняться. Время телевизора.</p><div class="actions">${btn('guide-refresh','Обновить','button',undefined,epgBusy?'disabled':'')}${btn('close-overlay','Назад','button')}</div>`,'guide','guide-sheet');}
function playbackChannels(){const all=F.orderedChannels(channels,channelOrder),fav=F.orderedChannels(all.filter(c=>favoriteChannels[c.url]),favoriteOrder);return channelFilter==='Избранные'&&fav.length?fav:all;}
function switchChannel(c){if(!c)return;lastChannelUrl=playing?.kind==='live'?playing.url:lastChannelUrl;lastLiveUrl=c.url;storage.set('lastLiveUrl',lastLiveUrl);channel=Math.max(0,channels.findIndex(n=>n.url===c.url));tv.querySelector('.overlay')?.remove();replacePlayback({kind:'live',url:c.url,title:c.name,channel:c});}
function stepChannel(step){const list=playbackChannels();if(!list.length)return;const index=list.findIndex(c=>c.url===playing?.url);switchChannel(list[(Math.max(0,index)+step+list.length)%list.length]);}
function quickChannels(){const list=F.orderedChannels(channels.filter(c=>favoriteChannels[c.url]),favoriteOrder);modal('Избранные каналы',`<div class="episode-list scroll">${list.map(c=>btn('quick-channel:'+channels.indexOf(c),esc(c.name),'button')).join('')||'<p>Добавьте каналы в избранное в разделе «Телеканалы».</p>'}</div>${btn('close-overlay','К эфиру','button')}`,'quick-channels');}
function openOrder(favoritesOnly=channelFilter==='Избранные'){
 orderFavorite=favoritesOnly;orderDraft=F.orderedChannels(channels.filter(c=>!favoritesOnly||favoriteChannels[c.url]),favoritesOnly?favoriteOrder:channelOrder).map(F.channelKey);orderOriginal=orderDraft.slice();orderGrab=-1;orderFocus=0;drawOrder();
}
function drawOrder(){const e=modal(orderFavorite?'Порядок избранных':'Порядок каналов',`<p id="order-help">${orderGrab>=0?'↑ ↓ — на 1 · ← → — на 10 позиций · OK — закрепить · Назад — отменить':'↑ ↓ — выбрать · OK — переместить · → — к кнопке «Сохранить»'}</p><div class="order-list scroll">${orderDraft.map((id,i)=>{const c=channels.find(c=>F.channelKey(c)===id);return btn('order-grab:'+i,`<span class="order-number">${i+1}</span><strong>${esc(c?.name||id)}</strong><span>${orderGrab>=0&&orderFocus===i?'↑ Перемещаем ↓':'↕'}</span>`,'button order-row '+(orderGrab>=0&&orderFocus===i?'moving':''),'order-'+i,`aria-label="${esc(c?.name||id)}, позиция ${i+1}${orderGrab>=0&&orderFocus===i?', перемещение':''}"`);}).join('')||'<p>Сначала добавьте каналы в избранное.</p>'}</div><div class="actions">${btn('order-save','Сохранить порядок','button primary')}${btn('order-cancel','Отмена','button')}</div>`,'channel-order','order-sheet');focus(findKey('order-'+orderFocus)||e.querySelector('button'));}
function orderKey(key){if(!orderDraft||!tv.querySelector('.order-sheet'))return false;if(orderGrab>=0){if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(key)){const step={ArrowUp:-1,ArrowDown:1,ArrowLeft:-10,ArrowRight:10}[key];const target=Math.max(0,Math.min(orderDraft.length-1,orderFocus+step));orderDraft=F.moveItem(orderDraft,orderFocus,target);orderFocus=target;drawOrder();return true;}if(key==='Enter'){orderGrab=-1;drawOrder();return true;}if(key==='Escape'||key==='Backspace'){orderDraft=F.moveItem(orderDraft,orderFocus,orderGrab);orderFocus=orderGrab;orderGrab=-1;drawOrder();return true;}return true;}
 const active=document.activeElement?.dataset.key||'',index=/^order-\d+$/.test(active)?Number(active.slice(6)):NaN;if(['order-save','order-cancel'].includes(active)&&key==='ArrowUp'&&orderDraft.length){focus(findKey('order-'+orderFocus));return true;}if(Number.isFinite(index)&&key==='ArrowRight'){orderFocus=index;focus(findKey('order-save'));return true;}if(Number.isFinite(index)&&['ArrowUp','ArrowDown'].includes(key)){if(key==='ArrowUp'&&index===0)return true;if(key==='ArrowDown'&&index===orderDraft.length-1)focus(findKey('order-save'));else{orderFocus=index+(key==='ArrowUp'?-1:1);focus(findKey('order-'+orderFocus));}return true;}return false;}
function featureAction(kind,v){
 if(kind==='history'){go('history',true);return true;}if(kind==='history-item'){historyMenu(v);return true;}
 if(kind==='history-play'||kind==='history-restart'){resumeHistory(v,kind==='history-restart');return true;}
 if(kind==='history-remove'||kind==='history-watched'){const r=history[v];if(r){if(kind==='history-remove')delete history[v];else{r.completed=!r.completed;if(fileProgress[fileKey(r)]){fileProgress[fileKey(r)].completed=r.completed;storage.set('fileProgress',fileProgress);}if(r.fileIndex!==undefined){const f=r.seriesEpisode||F.files(r.files||[]).find(f=>f.index===r.fileIndex);if(r.seriesEpisode){const progressKey=seriesProgressKey(r.movie,r.seriesEpisode);seriesProgress[progressKey]={...seriesProgress[progressKey],completed:r.completed,updated:Date.now()};storage.set('seriesProgress',seriesProgress);}if(f?.episode!=null){watched[episodeKey(r,f)]=r.completed;storage.set('watched',watched);}}}storage.set('history',history);}closeOverlay();render();return true;}
 if(kind==='episodes'){episodesDialog(awaitingFile);return true;}if(kind==='season'){episodeSeason=v==='other'?null:+v;episodesDialog(awaitingFile);return true;}if(kind==='episode'){selectEpisode(+v);return true;}
 if(kind==='cancel-files'||kind==='finish-playback'){awaitingFile=false;tv.querySelector('.overlay')?.remove();leavePlayer();return true;}
 if(kind==='player-tools'){playerTools();return true;}if(kind==='sleep-settings'){sleepDialog();return true;}if(kind==='sleep-set'){if(native)Native.command('sleep:'+v);closeOverlay();toast(+v===0?'Таймер выключен':+v===-1?'Просмотр остановится после текущего видео':'Просмотр остановится через '+v+' минут');return true;}
 if(kind==='diagnostics'){diagnosticsDialog();return true;}if(kind==='preferences'){preferenceDialog();return true;}
 if(kind==='pref-quality'){savePreferences({quality:v});return true;}if(kind==='pref-language'){savePreferences({language:v});return true;}if(kind==='pref-subtitles'){savePreferences({subtitles:!preferences.subtitles});return true;}
 if(kind==='guide'){guideDialog();if(!epgRequested)loadGuide();return true;}if(kind==='guide-refresh'){loadGuide(true);if(tv.querySelector('.guide-sheet'))guideDialog();else toast('Обновляем программу передач…');return true;}
 if(kind==='epg-source'){if(native)Native.input('epg');else toast('Ссылка XMLTV добавляется в APK');return true;}
 if(kind==='quick-channels'){quickChannels();return true;}if(kind==='quick-channel'){switchChannel(channels[+v]);return true;}if(kind==='previous-channel'){switchChannel(channels.find(c=>c.url===lastChannelUrl));return true;}
 if(kind==='channel-order'){openOrder();return true;}if(kind==='order-grab'){orderGrab=+v;orderFocus=+v;drawOrder();return true;}
 if(kind==='order-mode'){openOrder(!orderFavorite);return true;}if(kind==='order-cancel'){orderDraft=null;closeOverlay();return true;}
 if(kind==='order-save'){if(orderFavorite){favoriteOrder=orderDraft.slice();storage.set('favoriteOrder',favoriteOrder);}else{channelOrder=orderDraft.slice();storage.set('channelOrder',channelOrder);}orderDraft=null;closeOverlay();render();focus(findKey('channel-order'));toast('Порядок каналов сохранён');return true;}
 return false;
}

// Metadata-first series browsing and TV readability preferences.
