const seriesDetails=new Map();
let seriesProgress=storage.get('seriesProgress',{}),readability=F.readability(storage.get('readability',{})),pendingSeriesNext=null;
const seriesProgressKey=(m,e)=>'series:'+F.contentId(m)+':'+e.season+':'+e.episode;
const episodeLabel=e=>e?'Сезон '+e.season+' · Серия '+e.episode:'';
const compactMovie=m=>{if(!m)return m;const {videos,selectedEpisode,browseSeason,...rest}=m;return rest;};
const dateLabel=value=>{const date=new Date(value);return Number.isNaN(date.getTime())?'Дата выхода неизвестна':date.toLocaleDateString('ru',{day:'numeric',month:'long',year:'numeric'});};
function applyReadability(){tv.style.setProperty('--text-scale',({normal:1,large:1.15,largest:1.3})[readability.size]);document.body.dataset.textSize=readability.size;document.body.classList.toggle('strong-focus',readability.contrast);document.body.classList.toggle('reduce-motion',readability.motion);}
function readabilityDialog(){modal('Текст и выделение',`<p>Выберите удобный размер. Изменения видны сразу и сохраняются автоматически.</p><h3>Размер текста</h3><div class="chips">${[['normal','Обычный'],['large','Крупный'],['largest','Очень крупный']].map(([value,label])=>btn('text-size:'+value,label,'chip '+(readability.size===value?'selected':''),undefined,`aria-pressed="${readability.size===value}"`)).join('')}</div><div class="reading-preview"><strong>Название серии</strong><p>Описание, время просмотра и подсказки на экране.</p></div><div class="tool-list">${btn('reading-contrast','Усиленное выделение <small>'+(readability.contrast?'Включено':'Выключено')+'</small>','button',undefined,`aria-pressed="${readability.contrast}"`)}${btn('reading-motion','Меньше анимаций <small>'+(readability.motion?'Включено':'Выключено')+'</small>','button',undefined,`aria-pressed="${readability.motion}"`)}${btn('close-overlay','Готово','button primary')}</div><p class="small-label">Настройки относятся к интерфейсу «Смотрим». Размер субтитров и системных окон телевизора не меняется.</p>`,'readability','tools-sheet readability-sheet');focus(findKey('text-size:'+readability.size));}
function updateReadability(change,key){readability=F.readability({...readability,...change});storage.set('readability',readability);applyReadability();readabilityDialog();focus(findKey(key));}
function seriesScreen(){const pages=Math.max(1,Math.ceil(seriesItems.length/10));page=Math.min(page,pages-1);return `${sidebar()}${clock()}<section class="main catalog series-catalog"><div class="section-heading"><h1 class="page-title">Сериалы</h1>${btn('open-search:series',icon('search')+'Найти','button section-search','series-search')}</div><p class="lead">${seriesQuery?'По запросу «'+esc(seriesQuery)+'»':'Выберите сериал, сезон и серию — затем вариант просмотра.'}</p><div class="page-bar"><div class="actions">${seriesQuery?btn('series-reset','Все сериалы','button small'):''}${btn('series-reload',seriesBusy?'Обновляем…':'Обновить','button small',undefined,seriesBusy?'disabled':'')}${seriesHasMore?btn('series-more',catalogMoreBusy?'Загружаем…':'Ещё сериалы','button small',undefined,catalogMoreBusy?'disabled':''):''}</div>${pages>1?`<div class="pager">${btn('page:-1','←','button',undefined,`aria-label="Предыдущая страница" ${page===0?'disabled':''}`)}<span class="count">${page+1} из ${pages}</span>${btn('page:1','→','button',undefined,`aria-label="Следующая страница" ${page===pages-1?'disabled':''}`)}</div>`:''}</div>${seriesError?`<p class="catalog-notice" role="status">${esc(seriesError)}</p>`:''}<div class="movie-grid">${seriesBusy&&!seriesItems.length?loading('Ищем сериалы…'):seriesItems.length?seriesItems.slice(page*10,page*10+10).map(card).join(''):`<div class="empty"><h2>${seriesError?'Не удалось загрузить каталог':'Сериал не найден'}</h2><p>Попробуйте другое или оригинальное название. Можно также искать сразу по торрентам.</p>${btn('open-search:series','Изменить название','button')}${btn('series-direct-search','Искать по торрентам','button')}</div>`}</div></section>${hints([['OK','открыть сериал'],['Назад','вернуться']])}`;}
async function loadSeries(text='',push=false){const changed=text!==seriesQuery;seriesQuery=text;if(changed){seriesItems=[];page=0;delete focusMemory.series;}seriesBusy=true;seriesError='';const ticket=++seriesTicket;if(screen!=='series')go('series',push);else render();const focusAtStart=lastFocus;try{const rows=await rpc('catalog',{type:'series',query:text});if(ticket!==seriesTicket)return;seriesItems=(rows.items||rows).filter(m=>m.type==='series'&&m.id);seriesError=(rows.warnings||[]).join(' ');seriesHasMore=!!rows.hasMore;seriesRemotePage=1;}catch(e){if(ticket===seriesTicket)seriesError=(seriesItems.length?'Показан сохранённый список. ':'')+e.message;}finally{if(ticket===seriesTicket){seriesBusy=false;if(screen==='series'){if(lastFocus===focusAtStart&&!findKey(lastFocus)?.closest('.sidebar'))delete focusMemory.series;render();}}}}
