function seriesDetail(){const m=movie,list=F.catalogueEpisodes(m),season=seriesSeason(),seasons=seasonNumbers(m);return `${sidebar()}${clock()}<section class="main series-detail"><div class="series-summary"><div class="series-cover" ${art(m.poster||m.background)}></div><div><div class="eyebrow">${m.kind==='show'?'Шоу':'Сериал'} · ${esc(m.releaseInfo||year(m))}</div><h1>${esc(title(m))}</h1><p class="series-description">${esc(m.description||'Выберите сезон и серию.')}</p></div><div class="series-summary-actions">${seriesContinue(m)}${btn('favorite',icon(favorites[m.id]?'check':'plus')+(favorites[m.id]?'В избранном':'В избранное'),'button','detail-save')}${btn('series-all-sources','Поиск по названию','button')}${btn('series-detail-reload','Обновить серии','button',undefined,detailBusy?'disabled':'')}</div></div>${detailError||m.stale||m.metadataWarnings?.length?`<p class="catalog-notice" role="status">${esc(detailError||m.metadataWarnings?.[0]||'Показано сохранённое расписание. Даты новых серий могут измениться.')}</p>`:''}${metadataLanguageNotice(m)}${detailBusy&&!list.length?loading('Загружаем сезоны и серии…'):seasons.length?`<div class="series-browser"><div class="series-seasons scroll">${seasons.map(s=>btn('catalog-season:'+s,s===0?'Спецвыпуски':'Сезон '+s,'button '+(s===season?'selected':''),undefined,`data-catalog-season="${s}" aria-pressed="${s===season}"`)).join('')}</div><div class="catalog-episodes scroll">${seasonLoading===season?loading('Загружаем серии…'):list.filter(e=>e.season===season).map(e=>{const key=seriesProgressKey(m,e),progress=seriesProgress[key],done=watched[key],future=F.futureEpisode(e);return `<div class="catalog-episode"><button class="button catalog-episode-play" data-action="catalog-episode:${e.season}:${e.episode}" data-key="catalog-episode:${e.season}:${e.episode}" data-meta-episode="${e.season}:${e.episode}" ${list.find(v=>v.season===season&&!F.futureEpisode(v))===e?'data-initial':''} ${future?'disabled':''}><strong>Серия ${e.episode}${e.title&&!/^Episode \d+$|^Серия \d+$/i.test(e.title)?' · '+esc(e.title):''}</strong><small>${future?'Ожидается · ':''}${esc(dateLabel(e.released))}${done?' · Просмотрено':progress?.position?' · Продолжить с '+time(progress.position):''}</small>${e.description?'<span class="episode-description">'+esc(e.description)+'</span>':''}</button>${btn('catalog-watched:'+e.season+':'+e.episode,icon(done?'check':'plus'),'button episode-mark',undefined,`data-meta-mark="${e.season}:${e.episode}" aria-label="${done?'Снять отметку':'Отметить просмотренной'}: сезон ${e.season}, серия ${e.episode}" aria-pressed="${!!done}" ${future?'disabled':''}`)}</div>`;}).join('')}</div></div>`:`<div class="empty"><h2>Список серий пока недоступен</h2><p>Можно повторить загрузку или найти раздачи по названию сериала.</p></div>`}<p class="series-footnote">OK — найти варианты серии · → — отметка просмотра. Даты выхода не гарантируют наличие раздач.</p></section>${hints([['↑ ↓','серии'],['←','сезоны'],['Назад','вернуться']])}`;}
async function openSeries(selected,push=true,refresh=false){const id=selected.id;seasonTicket++;seasonLoading=null;movie=adoptIdentity({...selected,...seriesDetails.get(id),searchName:selected.searchName||seriesDetails.get(id)?.searchName,searchHint:selected.searchHint||seriesDetails.get(id)?.searchHint,selectedEpisode:null});detailError='';detailBusy=true;const ticket=++detailTicket;if(screen!=='series-detail')go('series-detail',push);else render();const loadingFocus=lastFocus;try{const value=await rpc('series-detail',{id,item:selected,refresh});seriesDetails.set(id,value);if(ticket!==detailTicket||screen!=='series-detail'||movie.id!==id)return;movie=adoptIdentity({...movie,...value});if(lastFocus===loadingFocus)delete focusMemory['series-detail'];}catch(e){if(ticket===detailTicket)detailError=e.message;}finally{if(ticket===detailTicket){detailBusy=false;if(screen==='series-detail'&&movie.id===id)render();}}}
function openCatalogueEpisode(season,episode){const chosen=F.catalogueEpisodes(movie).find(e=>e.season===season&&e.episode===episode);if(!chosen||F.futureEpisode(chosen))return;movie={...movie,selectedEpisode:chosen,browseSeason:season};focusMemory['series-detail']='catalog-episode:'+season+':'+episode;delete focusMemory.sources;go('sources',true);loadSources();}
function markCatalogueEpisode(season,episode){const e=F.catalogueEpisodes(movie).find(v=>v.season===season&&v.episode===episode);if(!e||F.futureEpisode(e))return;const key=seriesProgressKey(movie,e),done=!watched[key];watched[key]=done;seriesProgress[key]={...seriesProgress[key],completed:done,updated:Date.now()};storage.set('watched',watched);storage.set('seriesProgress',seriesProgress);const r=history['series:'+F.contentId(movie)];if(r?.seriesEpisode?.season===season&&r.seriesEpisode.episode===episode){r.completed=done;storage.set('history',history);}render();focus(findKey('catalog-watched:'+season+':'+episode));}
function seriesNavigation(key){if(screen!=='series-detail'||tv.querySelector('.overlay'))return false;const el=document.activeElement,isMark=el?.dataset.metaMark!==undefined,ref=el?.dataset.metaEpisode||el?.dataset.metaMark;if(ref){const play=findKey('catalog-episode:'+ref);if(key==='ArrowLeft'){focus(isMark?play:findKey('catalog-season:'+seriesSeason()));return true;}if(key==='ArrowRight'){focus(findKey('catalog-watched:'+ref));return true;}if(['ArrowUp','ArrowDown'].includes(key)){const rows=Array.from(tv.querySelectorAll('[data-meta-episode]:not(:disabled)')),i=rows.indexOf(play),next=rows[i+(key==='ArrowDown'?1:-1)];if(next)focus(isMark?findKey('catalog-watched:'+next.dataset.metaEpisode):next);else if(key==='ArrowUp')focus(findKey('catalog-season:'+seriesSeason()));return true;}}if(el?.dataset.catalogSeason!==undefined&&key==='ArrowRight'){focus(tv.querySelector('[data-meta-episode]:not(:disabled)'));return true;}return false;}
function requestedEpisode(file){if(playing?.movie?.type!=='series')return null;const target=playing.seriesEpisode;if(file?.episode!=null)return F.catalogueEpisodes(playing.movie).find(e=>e.season===file.season&&e.episode===file.episode)||{season:file.season,episode:file.episode};return target||null;}
function chooseCatalogueFile(files){if(!playing?.seriesEpisode)return false;const matching=F.matchingFiles(files,playing.seriesEpisode),saved=matching.find(f=>f.index===playing.fileIndex),match=saved||(matching.length===1?matching[0]:null);if(!match)return false;awaitingFile=true;selectEpisode(match.index);return true;}
async function hydratePlayingSeries(){const item=playing;if(item?.movie?.type!=='series'||item.movie.videos)return;try{const m=await rpc('series-detail',{id:item.movie.id,item:item.movie});if(playing===item)item.movie={...item.movie,...m};}catch(_){}}
function seriesAction(kind,v){
 if(kind==='readability'){readabilityDialog();return true;}if(kind==='text-size'){updateReadability({size:v},kind+':'+v);return true;}if(kind==='reading-contrast'){updateReadability({contrast:!readability.contrast},kind);return true;}if(kind==='reading-motion'){updateReadability({motion:!readability.motion},kind);return true;}
 if(kind==='nav'&&v==='series'){page=0;go('series');loadSeries('');return true;}
 if(kind==='series-reload'||kind==='series-reset'){loadSeries(kind==='series-reset'?'':seriesQuery);return true;}
 if(kind==='series-direct-search'){if(!seriesQuery.trim()){openSearch('torrents');return true;}movie={name:seriesQuery,id:'',searchQuery:true};go('sources',true);loadSources();return true;}
 if(kind==='series-detail-reload'){openSeries(movie,false,true);return true;}
 if(kind==='series-all-sources'){movie={...movie,selectedEpisode:null};go('sources',true);loadSources();return true;}
 if(kind==='catalog-season'){loadSeason(+v);return true;}
 if(kind==='catalog-episode'||kind==='catalog-watched'){const [s,e]=v.split(':').map(Number);if(kind==='catalog-episode')openCatalogueEpisode(s,e);else markCatalogueEpisode(s,e);return true;}
 if(kind==='player-series'){pendingSeriesNext={movie:playing.movie,episode:null};tv.querySelector('.overlay')?.remove();leavePlayer('series-next');return true;}
 if(kind==='next-catalogue'){const next=F.nextCatalogueEpisode(playing.movie,playing.seriesEpisode);if(next){pendingSeriesNext={movie:playing.movie,episode:next};tv.querySelector('.overlay')?.remove();leavePlayer('series-next');}return true;}
 return false;
}

let resultItems=[],resultQuery='',resultKind='all',resultOrigin='all',resultBusy=false,resultError='',resultWarnings=[],resultMore=false,resultRemotePage=1,resultTicket=0;
let movieDetailError='';
let catalogProviders={kinopoisk:false,tmdb:false},catalogWarnings=[],catalogOrigin='all',catalogHasMore=false,catalogRemotePage=1,catalogMoreBusy=false,seriesHasMore=false,seriesRemotePage=1,seasonLoading=null,seasonTicket=0;
const mediaKind=m=>({movie:'Фильм',series:'Сериал',show:'Шоу'})[m?.kind||m?.type]||'Фильм';
const originButton=(action,value)=>btn(action,({all:'Все страны',ru:'Россия и СССР',other:'Другие страны'})[value],'chip',undefined,`aria-label="Страна: ${({all:'все',ru:'Россия и СССР',other:'другие страны'})[value]}. OK — изменить"`);
const nextOrigin=value=>({all:'ru',ru:'other',other:'all'})[value]||'all';
function catalogNotice(){return `<div class="catalog-status">${originButton('catalog-origin',catalogOrigin)}<span>${esc(catalogWarnings[0]||'Международное и популярное в России · без повторов')}</span>${catalogHasMore?btn('catalog-more',catalogMoreBusy?'Загружаем…':'Ещё фильмы','button small',undefined,catalogMoreBusy?'disabled':''):''}</div>`;}
function resultCard(m,i){return btn('movie:'+m.id,`<div class="result-cover" ${art(m.poster||m.background)}></div><div class="result-copy"><strong>${esc(title(m))}</strong><small>${esc([year(m),mediaKind(m),m.imdbRating?'★ '+m.imdbRating:''].filter(Boolean).join(' · '))}</small><p>${esc(m.description||genreText(m)||'Откройте карточку: описание и варианты просмотра.')}</p></div>`,'result-card','movie-'+m.id,i===0?'data-initial':'');}
function resultsScreen(){const rows=F.filterMedia(resultItems,resultKind,resultOrigin),pages=Math.max(1,Math.ceil(rows.length/6));page=Math.min(page,pages-1);return `${sidebar()}${clock()}<section class="main catalog-results"><div class="section-heading"><h1 class="page-title">Результаты поиска</h1>${btn('results-edit',icon('search')+'Изменить','button section-search')}</div><p class="lead result-query">«${esc(resultQuery)}»</p><div class="page-bar"><div class="chips">${[['all','Всё'],['movie','Фильмы'],['series','Сериалы'],['show','Шоу']].map(([k,n])=>btn('result-kind:'+k,n,'chip '+(k===resultKind?'selected':''),undefined,`aria-pressed="${k===resultKind}"`)).join('')}${originButton('result-origin',resultOrigin)}</div><div class="pager">${btn('page:-1','←','button',undefined,`aria-label="Предыдущая страница" ${page===0?'disabled':''}`)}<span>${page+1} / ${pages}</span>${btn('page:1','→','button',undefined,`aria-label="Следующая страница" ${page===pages-1?'disabled':''}`)}</div></div><p class="catalog-notice" role="status">${esc(resultError||resultWarnings[0]||'Выберите фильм или сериал. Качество и озвучка — после кнопки «Смотреть».')}</p><div class="result-grid">${resultBusy&&!resultItems.length?loading('Ищем фильмы, сериалы и шоу…'):rows.length?rows.slice(page*6,page*6+6).map(resultCard).join(''):`<div class="empty"><h2>${resultError?'Поиск временно недоступен':resultItems.length?'Нет карточек с этими фильтрами':'Пока ничего не найдено'}</h2><p>${resultItems.length?'Выберите «Всё» и «Все страны». Страна известна не у всех карточек.':'Проверьте название или попробуйте поиск по раздачам.'}</p>${btn('results-retry','Повторить поиск','button')}${btn('catalog-settings','Подключить каталоги','button')}</div>`}</div><div class="results-footer">${btn('results-direct','Не нашли? Искать по раздачам','button')}${resultMore?btn('results-more',resultBusy?'Загружаем…':'Загрузить ещё','button',undefined,resultBusy?'disabled':''):''}<span>Карточек: ${rows.length}${resultMore?' · есть ещё':''}</span></div></section>${hints([['OK','открыть карточку'],['Назад','к вводу']])}`;}
async function searchCatalog(text,more=false){
 if(resultBusy&&more)return;
 if(!more){resultQuery=text;resultItems=[];resultKind=searchMode==='movies'?'movie':searchMode==='series'?'series':searchMode==='show'?'show':'all';resultOrigin='all';resultRemotePage=1;resultMore=false;delete focusMemory.results;if(screen!=='results')go('results',true);page=0;}
 resultBusy=true;resultError='';resultWarnings=[];const ticket=++resultTicket,requestedPage=more?resultRemotePage+1:1;render();const waitingFocus=lastFocus;
 try{const response=await rpc('catalog',{query:resultQuery,type:'movie',page:requestedPage});if(ticket!==resultTicket)return;resultItems=F.uniqueMedia(resultItems.concat(response.items||response)).slice(0,600);resultWarnings=response.warnings||[];resultMore=!!response.hasMore&&resultItems.length<600;resultRemotePage=requestedPage;if(response.providers)catalogProviders=response.providers;
 }catch(e){if(ticket===resultTicket)resultError=e.message;}finally{if(ticket===resultTicket){resultBusy=false;if(screen==='results'){if(!more&&lastFocus===waitingFocus&&!findKey(lastFocus)?.closest('.sidebar'))delete focusMemory.results;render();}}}
}
function directSearch(text){if(!text.trim()){openSearch('torrents');return;}movie={id:'',name:text.trim(),searchQuery:true,genres:[]};delete focusMemory.sources;go('sources',true);loadSources();}
function adoptIdentity(value){const m={...value},all=[...Object.values(history).map(r=>r.movie),...Object.values(favorites)],known=all.find(v=>F.sameMedia(v,m));const savedId=F.mediaIds(m).find(id=>Object.keys(seriesProgress).concat(Object.keys(watched)).some(key=>key.startsWith('series:'+id+':')));m.historyId=known?F.contentId(known):savedId||F.contentId(m);for(const [key,f] of Object.entries(favorites))if(F.sameMedia(f,m)){delete favorites[key];favorites[m.id]={...f,...compactMovie(m)};storage.set('favorites',favorites);}return m;}
function metadataLanguageNotice(m){const texts=[m.description||m.name,...(m.videos||[]).slice(0,30).map(v=>v.description||v.title)];if(!texts.some(t=>/[A-Za-z]{3}/.test(t||'')&&!/[А-Яа-яЁё]/.test(t||'')))return '';const connected=catalogProviders.kinopoisk||catalogProviders.tmdb||catalogProviders.github;return `<div class="catalog-language-notice"><span>${connected?'Каталог не вернул русский перевод части описаний.':'Русские описания не подключены. Показан текст исходного каталога.'}</span>${btn('catalog-settings',connected?'Проверить каталоги':'Русские описания','button small','catalog-settings')}</div>`;}
function catalogSettings(){const own=catalogProviders.github;modal('Каталоги фильмов и сериалов',`<p>В подборке Смотрим — российские и зарубежные фильмы и сериалы с русскими карточками. Для неё ключи не нужны.</p><div class="tool-list">${btn('github-refresh','Обновить подборку Смотрим <small>'+(own?esc(own.count)+' карточек · '+esc(new Date(own.updatedAt).toLocaleDateString('ru-RU')):'Проверить GitHub')+'</small>','button')}${btn('catalog-key:kp','Расширенный русский каталог <small>Kinopoisk API Unofficial · '+(catalogProviders.kinopoisk?'Подключён':'Можно добавить личный ключ')+'</small>','button')}${btn('catalog-key:tmdb','Международный каталог <small>TMDB · '+(catalogProviders.tmdb?'Подключён':'Можно добавить личный ключ')+'</small>','button')}${btn('close-overlay','Готово','button primary')}</div>${own?.error?'<p role="status">'+esc(own.error)+'</p>':''}<p class="small-label">При запуске подборка обновляется с GitHub. Без сети остаётся сохранённая версия. Поиск других названий работает через внешние каталоги.</p>`,'catalog-settings');}
async function refreshGithub(force=false){try{const response=await rpc('github-refresh',{force});catalogProviders=response.providers||catalogProviders;if(response.changed){seriesDetails.clear();await refreshCatalog(true);if(screen==='series')await loadSeries(seriesQuery);}if(force){if(tv.querySelector('.overlay')){closeOverlay();catalogSettings();}toast(catalogProviders.github?.error||'Подборка актуальна');}}catch(e){if(force)toast('Не удалось обновить подборку. Сохранённые карточки доступны.');}}
const seasonNumbers=m=>[...new Set([...(m?.seasons||[]).map(s=>s.number),...F.catalogueEpisodes(m).map(v=>v.season)])].filter(Number.isInteger).sort((a,b)=>a-b);
function seriesContinue(m){const r=history['series:'+F.contentId(m)];return r&&!r.completed?btn('series-continue',icon('play')+'Продолжить','button primary','series-continue'):'';}
async function loadSeason(season){movie={...movie,browseSeason:season};const selected=movie,ticket=++seasonTicket;seasonLoading=null;render();focus(findKey('catalog-season:'+season));if(movie.episodeProvider==='kp'||(movie.loadedSeasons||[]).includes(season)||!movie.tmdbId)return;
 seasonLoading=season;detailError='';render();try{const rows=await rpc('series-season',{item:compactMovie(movie),season});if(ticket!==seasonTicket||movie.id!==selected.id||screen!=='series-detail')return;movie={...movie,videos:[...(movie.videos||[]).filter(v=>v.season!==season),...rows],loadedSeasons:[...(movie.loadedSeasons||[]),season]};seriesDetails.set(movie.id,movie);if(!rows.length)detailError='В этом сезоне пока нет серий.';}catch(e){if(ticket===seasonTicket)detailError=e.message;}finally{if(ticket===seasonTicket){seasonLoading=null;if(screen==='series-detail')render();}}}
async function morePopular(series=false){if(catalogMoreBusy)return;catalogMoreBusy=true;render();try{const next=(series?seriesRemotePage:catalogRemotePage)+1,response=await rpc('catalog',{type:series?'series':'movie',page:next});if(series){seriesItems=F.uniqueMedia(seriesItems.concat(response.items||[])).slice(0,600);seriesHasMore=!!response.hasMore&&seriesItems.length<600;seriesRemotePage=next;}else{movies=catalog=F.uniqueMedia(catalog.concat(response.items||[])).slice(0,600);catalogWarnings=response.warnings||[];catalogHasMore=!!response.hasMore&&catalog.length<600;catalogRemotePage=next;}}catch(e){toast(e.message);}finally{catalogMoreBusy=false;if(['catalog','series'].includes(screen))render();}}
function catalogAction(kind,v){
 if(kind==='result-kind'){resultKind=v;page=0;render();focus(findKey(kind+':'+v));return true;}
 if(kind==='result-origin'||kind==='catalog-origin'){if(kind==='result-origin')resultOrigin=nextOrigin(resultOrigin);else catalogOrigin=nextOrigin(catalogOrigin);page=0;render();focus(findKey(kind));return true;}
 if(kind==='results-edit'){query=resultQuery;queryCursor=query.length;back();return true;}
 if(kind==='results-retry'){searchCatalog(resultQuery);return true;}
 if(kind==='results-more'){searchCatalog(resultQuery,true);return true;}
 if(kind==='results-direct'){directSearch(resultQuery);return true;}
 if(kind==='catalog-more'||kind==='series-more'){morePopular(kind==='series-more');return true;}
 if(kind==='catalog-settings'){catalogSettings();return true;}
 if(kind==='github-refresh'){refreshGithub(true);return true;}
 if(kind==='catalog-key'){if(native)Native.input('catalog-'+v);else toast('Подключение каталогов доступно в APK на телевизоре');return true;}
 if(kind==='series-continue'){resumeHistory('series:'+F.contentId(movie));return true;}
 return false;
}

function scheduleHomeFeed(){
 if(!homeFeedReady||!native||!Native.publishHome)return;
 clearTimeout(homeFeedTimer);homeFeedTimer=setTimeout(publishHomeFeed,80);
}
function publishHomeFeed(){
 if(!homeFeedReady||!native||!Native.publishHome)return;
 clearTimeout(homeFeedTimer);
 try{Native.publishHome(JSON.stringify(window.HomeFeed.snapshot({history,channels,favoriteChannels,favoriteOrder},title,safeImage,F.orderedChannels,F.channelKey)));}catch(_){}
}
function openFromHome(item){
 if(!item)return;
 if(item.kind==='history'){
  if(!history[item.key]){toast('Этого видео уже нет в истории просмотра');return;}
  if(playing&&playing.historyKey===item.key&&!playError){screen='player';render();showControls();return;}
  if(playing)persistProgress(playState.position);
  stack=[];screen='home';resumeHistory(item.key);return;
 }
 if(item.kind==='channels'){
  const selected=channels.find(c=>F.channelKey(c)===item.key);
  if(!selected){openFromHome({kind:'tv'});toast('Канал больше не доступен. Выберите другой в списке.');return;}
  if(playing?.kind==='live'&&playing.url===selected.url&&!playError){screen='player';render();showControls();return;}
  if(playing)persistProgress(playState.position);
  stack=[];screen='home';channel=channels.indexOf(selected);start({kind:'live',url:selected.url,title:selected.name,channel:selected});return;
 }
 if(item.kind==='tv'){if(playing){persistProgress(playState.position);Native.command('stop');playing=null;playState={};}go('tv');}
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)publishHomeFeed();});


